// The executor sends { incident_id, input: { action, target, ...tool_args } }.
const body = $input.first().json.body ?? $input.first().json;
const input = body.input ?? {};

return [{
  json: {
    incident_id: body.incident_id ?? 'unknown',
    action: input.action ?? 'isolate_host',
    target: input.target ?? '',
    reason: input.reason ?? input.justification ?? '',
  },
}];

// ── SIMULATION ─────────────────────────────────────────────────────────
// Replace this node with your real containment call when going live, e.g.
//   CrowdStrike : POST /devices/entities/devices-actions/v2?action_name=contain
//   Defender    : POST /api/machines/{id}/isolate
//   Entra ID    : PATCH /users/{id}  { accountEnabled: false }
//   Palo Alto   : add address to a dynamic block list
//
// Everything below fabricates a plausible success response. It is marked
// simulated:true so the record never claims a real action was taken.
const { incident_id, action, target, reason } = $input.first().json;

const ticket = 'CONTAIN-' + String(Math.abs(
  [...(incident_id + target)].reduce((a, c) => (a * 31 + c.charCodeAt(0)) | 0, 7)
) % 100000).padStart(5, '0');

return [{
  json: {
    simulated: true,
    status: 'success',
    action,
    target,
    reason,
    incident_id,
    containment_id: ticket,
    isolated_at: new Date().toISOString(),
    network_access: action === 'isolate_host' ? 'blocked except management' : 'unchanged',
    reversible_via: 'lift_containment with containment_id ' + ticket,
    note: 'SIMULATED action — no real system was modified.',
  },
}];
